import React, { useState, useEffect, useMemo } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { motion } from 'framer-motion';
import { 
  FileText, 
  X, 
  Eye
} from 'lucide-react';
import './OCRProcessing.css';

const OCRProcessing = () => {
  const navigate = useNavigate();
  const location = useLocation();
  
  // Get PDF data from navigation state or use mock data
  const pdfData = useMemo(() => location.state?.pdf || {
    id: 1,
    title: 'Scanned Document.pdf',
    pages: 12,
    size: '4.2 MB'
  }, [location.state?.pdf]);

  const [progress, setProgress] = useState(0);
  const [currentStep, setCurrentStep] = useState(0);
  const [isComplete, setIsComplete] = useState(false);

  // Swiggy-style processing steps with fun messages
  const processingSteps = [
    { message: "🔍 Scanning your document...", subtext: "Looking for text and images" },
    { message: "📄 Extracting pages...", subtext: "Breaking down the PDF structure" },
    { message: "🤖 Running OCR magic...", subtext: "Converting images to searchable text" },
    { message: "✨ Optimizing for reflow...", subtext: "Making text beautiful and readable" },
    { message: "🎉 Almost ready!", subtext: "Preparing your enhanced document" },
    { message: "✅ All done!", subtext: "Your document is ready to read" }
  ];

  // Auto-start processing with Swiggy-style progress
  useEffect(() => {
    const totalDuration = 3000; // 3 seconds total
    const stepDuration = totalDuration / processingSteps.length;
    
    const progressTimer = setInterval(() => {
      setProgress(prev => {
        const newProgress = prev + (100 / (totalDuration / 100));
        if (newProgress >= 100) {
          clearInterval(progressTimer);
          setIsComplete(true);
          // Auto-navigate to reader after completion
          setTimeout(() => {
            navigate(`/reader/${pdfData.id}`, { 
              state: { 
                pdf: pdfData, 
                mode: 'reflow',
                ocrComplete: true 
              } 
            });
          }, 1000);
          return 100;
        }
        return newProgress;
      });
    }, 100);

    // Update step messages
    const stepTimer = setInterval(() => {
      setCurrentStep(prev => {
        const newStep = prev + 1;
        if (newStep >= processingSteps.length) {
          clearInterval(stepTimer);
          return processingSteps.length - 1;
        }
        return newStep;
      });
    }, stepDuration);

    return () => {
      clearInterval(progressTimer);
      clearInterval(stepTimer);
    };
  }, [pdfData, navigate, processingSteps.length]);

  const currentStepData = processingSteps[currentStep] || processingSteps[0];

  const handleCancel = () => {
    navigate('/dashboard');
  };

  const handleContinueOriginal = () => {
    navigate(`/reader/${pdfData.id}`, { 
      state: { 
        pdf: pdfData, 
        mode: 'original' 
      } 
    });
  };

  return (
    <div className="ocr-processing">
      <div className="ocr-container">
        {/* Header */}
        <motion.div 
          className="ocr-header"
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.5 }}
        >
          <div className="header-content">
            <div className="document-info">
              <FileText className="document-icon" size={24} />
              <div className="document-details">
                <h1 className="document-title">{pdfData.title}</h1>
                <p className="document-meta">{pdfData.pages} pages • {pdfData.size}</p>
              </div>
            </div>
            <button 
              className="close-button"
              onClick={handleCancel}
              aria-label="Close OCR processing"
            >
              <X size={20} />
            </button>
          </div>
        </motion.div>

        {/* Main Content - Swiggy Style */}
        <div className="ocr-main">
          <motion.div 
            className="swiggy-progress-section"
            initial={{ opacity: 0, y: 30 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6 }}
          >
            {/* Fun Processing Animation */}
            <div className="processing-animation">
              <motion.div 
                className="processing-icon"
                animate={{ 
                  rotate: isComplete ? 0 : 360,
                  scale: isComplete ? 1.2 : 1
                }}
                transition={{ 
                  rotate: { duration: 2, repeat: isComplete ? 0 : Infinity, ease: "linear" },
                  scale: { duration: 0.3 }
                }}
              >
                {isComplete ? '🎉' : '🤖'}
              </motion.div>
            </div>

            {/* Current Step Message */}
            <motion.div 
              className="step-message"
              key={currentStep}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.4 }}
            >
              <h2 className="step-title">{currentStepData.message}</h2>
              <p className="step-subtitle">{currentStepData.subtext}</p>
            </motion.div>

            {/* Progress Bar */}
            <div className="swiggy-progress-container">
              <div className="progress-track">
                <motion.div 
                  className="progress-fill"
                  initial={{ width: 0 }}
                  animate={{ width: `${progress}%` }}
                  transition={{ duration: 0.3, ease: "easeOut" }}
                />
              </div>
              <div className="progress-percentage">
                {Math.round(progress)}%
              </div>
            </div>

            {/* Processing Steps Indicator */}
            <div className="steps-indicator">
              {processingSteps.map((step, index) => (
                <motion.div
                  key={index}
                  className={`step-dot ${index <= currentStep ? 'active' : ''} ${index < currentStep ? 'completed' : ''}`}
                  initial={{ scale: 0 }}
                  animate={{ scale: 1 }}
                  transition={{ delay: index * 0.1 }}
                >
                  {index < currentStep ? '✓' : index === currentStep ? '●' : '○'}
                </motion.div>
              ))}
            </div>

            {/* Completion Message */}
            {isComplete && (
              <motion.div 
                className="completion-message"
                initial={{ opacity: 0, scale: 0.8 }}
                animate={{ opacity: 1, scale: 1 }}
                transition={{ duration: 0.5 }}
              >
                <p>Opening your enhanced document...</p>
              </motion.div>
            )}
          </motion.div>
        </div>

        {/* Simple Actions */}
        {!isComplete && (
          <motion.div 
            className="ocr-actions"
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5, delay: 0.3 }}
          >
            <button 
              className="action-button outline"
              onClick={handleContinueOriginal}
            >
              <Eye size={16} />
              Skip & View Original
            </button>
            
            <button 
              className="action-button danger"
              onClick={handleCancel}
            >
              <X size={16} />
              Cancel
            </button>
          </motion.div>
        )}
      </div>
    </div>
  );
};

export default OCRProcessing;
